/**
 * @summary Stateless calculation of an estimate (no persistence)
 */

export const PreviewCalculationBody = zod.object({
  installType: zod.enum(["new_install", "retrofit", "deinstall"]),
  buildingType: zod.enum(["office", "warehouse", "retail", "healthcare"]),
  environment: zod.enum(["occupied", "unoccupied"]),
  skillLevel: zod.enum(["apprentice", "journeyman", "lead"]),
  hourlyRate: zod.number(),
  runs: zod.array(
    zod.object({
      label: zod.string(),
      cableType: zod.string(),
      description: zod.string().nullish(),
      numCables: zod.number(),
      fiberStrands: zod.number().min(1).optional(),
      lengthFt: zod.number(),
      ceilingType: zod.enum(["open", "drywall", "hard_lid"]),
      pathwayComplexity: zod.enum(["low", "medium", "high"]),
    }),
  ),
});

export const PreviewCalculationResponse = zod.object({
  runs: zod.array(
    zod
      .object({
        runId: zod.number().optional(),
        label: zod.string(),
        cableType: zod.string(),
        description: zod.string().nullish(),
        numCables: zod
          .number()
          .describe(
            "Cables pulled simultaneously (B) — drives the bulk factor",
          ),
        fiberStrands: zod
          .number()
          .optional()
          .describe(
            "Strands per fiber cable; multiplies termination labor (1 for non-fiber)",
          ),
        lengthFt: zod.number(),
        ceilingType: zod.enum(["open", "drywall", "hard_lid"]),
        pathwayComplexity: zod.enum(["low", "medium", "high"]),
        bulkFactor: zod
          .number()
          .describe("Computed efficiency factor: 0.4 + (0.6 \/ numCables)"),
        pullMinutesPer10Ft: zod
          .number()
          .describe("Base pull rate in minutes per 10 ft for this cable type"),
        terminationMinutesPerEnd: zod
          .number()
          .describe(
            "Base termination time in minutes per end for this cable type",
          ),
        conditionMultiplier: zod
          .number()
          .describe(
            "Combined site\/condition multiplier (install × ceiling × pathway × building × environment × skill)",
          ),
        pullHoursPerCable: zod
          .number()
          .describe(
            "Pull hours for one cable within a single bulk pass (after condition mult + bulk factor)",
          ),
        terminationHoursPerCable: zod
          .number()
          .describe(
            "Termination hours per cable (both ends, after condition mult — NOT bulk-discounted)",
          ),
        adjustedHoursPerCable: zod
          .number()
          .describe(
            "Average total hours per cable = (totalPullHours + totalTermHours) \/ numCables",
          ),
        runHoursLow: zod.number(),
        runHoursAvg: zod.number(),
        runHoursHigh: zod.number(),
        runCostLow: zod.number(),
        runCostAvg: zod.number(),
        runCostHigh: zod.number(),
      })
      .describe("Computed labor breakdown for a single cable run group"),
  ),
  totals: zod.object({
    totalCables: zod.number(),
    totalRuns: zod.number(),
    totalHoursLow: zod.number(),
    totalHoursAvg: zod.number(),
    totalHoursHigh: zod.number(),
    totalCostLow: zod.number(),
    totalCostAvg: zod.number(),
    totalCostHigh: zod.number(),
    bulkSavingsHours: zod
      .number()
      .describe(
        "Hours saved by pulling cables in a single bulk pass vs. pulling each one solo",
      ),
    taskBreakdown: zod.array(
      zod.object({
        task: zod.string(),
        percent: zod.number(),
        hoursAvg: zod.number(),
        costAvg: zod.number(),
      }),
    ),
  }),
});
